package com.compassonly;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;

/**
 * Makes the bank wider so it shows more items per row.
 *
 * The game's bank script always lays items out 8 to a row in a fixed-width area, and
 * resets that width every time it rebuilds the bank. So this widens the window and then
 * moves the item slots into a wider grid itself, again after every rebuild. It is still
 * the real bank, so clicking and dragging items work as normal.
 */
class BankWidener
{
	static final int DEFAULT_COLUMNS = 8;

	// Taken from the game's bank layout script
	private static final int SLOT_WIDTH = 36;
	private static final int SLOT_HEIGHT = 32;
	private static final int ROW_HEIGHT = 36;
	private static final int COLUMN_SPACING = 48;
	private static final int FIRST_COLUMN_X = 51;
	private static final int SCROLL_PADDING = 8;
	private static final int DIVIDER_LINE_HEIGHT = 2;
	private static final int DIVIDER_LABEL_HEIGHT = 15;
	// Space the game leaves beside the dividers: 51 on the left and 35 on the right
	private static final int DIVIDER_SIDE_SPACE = 86;

	// Taken from RuneLite's Bank Tags plugin, which adds its tabs to the bank
	private static final int TAG_TAB_FIRST_CHILD = 4;
	private static final int TAG_TAB_WIDTH = 39;
	private static final int TAG_TAB_HEIGHT = 40;
	private static final int TAG_TAB_MARGIN = 1;
	private static final int TAG_ICON_INSET_X = 3;
	private static final int TAG_ICON_INSET_Y = 4;

	private static final Comparator<Widget> TOP_TO_BOTTOM = Comparator
		.comparingInt(Widget::getOriginalY)
		.thenComparingInt(Widget::getOriginalX);

	private final Client client;

	// The bank's widths before they were changed, or -1 while it is untouched
	private int baseWindowWidth = -1;
	private int baseItemsWidth = -1;
	private int appliedColumns = DEFAULT_COLUMNS;

	// The game's shared window box, widened while the bank is, and its normal width
	private Widget modalWidget;
	private int baseModalWidth = -1;

	private boolean tabRowApplied;
	private boolean hidTagArrows;

	BankWidener(Client client)
	{
		this.client = client;
	}

	/**
	 * Called before every frame. Cheap unless the bank has just been rebuilt.
	 */
	void update(int requestedColumns)
	{
		final Widget window = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		final Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (window == null || items == null || window.isHidden())
		{
			// The bank has closed, so give other windows their normal space back
			restoreModal();
			baseWindowWidth = -1;
			baseItemsWidth = -1;
			appliedColumns = DEFAULT_COLUMNS;
			tabRowApplied = false;
			hidTagArrows = false;
			return;
		}

		// The bank sits inside a fixed-width box the game uses for all of its windows,
		// which would cut off anything wider. That box is centred in the space left of
		// the side panel, and that space is the real limit.
		final Widget holder = window.getParent();
		final Widget modal = holder == null ? null : holder.getParent();
		final Widget space = modal == null ? null : modal.getParent();
		if (space == null)
		{
			return;
		}

		final boolean touched = baseWindowWidth != -1;
		final int modalWidth = modalWidget == modal ? baseModalWidth : modal.getOriginalWidth();
		final int maxColumns = DEFAULT_COLUMNS + Math.max(0, space.getWidth() - modalWidth) / COLUMN_SPACING;
		final int columns = Math.min(Math.max(requestedColumns, DEFAULT_COLUMNS), maxColumns);
		if (columns == DEFAULT_COLUMNS && !touched)
		{
			layoutTabRow(true);
			return;
		}

		if (!touched)
		{
			baseWindowWidth = window.getOriginalWidth();
			baseItemsWidth = items.getOriginalWidth();
		}
		if (modalWidget != modal)
		{
			restoreModal();
			modalWidget = modal;
			baseModalWidth = modal.getOriginalWidth();
		}

		final int extra = (columns - DEFAULT_COLUMNS) * COLUMN_SPACING;
		final int wantedModalWidth = baseModalWidth + extra;
		final int wantedWindowWidth = baseWindowWidth + extra;
		final int wantedItemsWidth = baseItemsWidth + extra;

		// The game puts the item area back to its normal width whenever it rebuilds the
		// bank, which is also the sign that the slots are back in 8 columns
		final boolean rebuilt = items.getOriginalWidth() != wantedItemsWidth;
		if (rebuilt || modal.getOriginalWidth() != wantedModalWidth
			|| window.getOriginalWidth() != wantedWindowWidth || columns != appliedColumns)
		{
			items.setOriginalWidth(wantedItemsWidth);
			window.setOriginalWidth(wantedWindowWidth);
			modal.setOriginalWidth(wantedModalWidth);
			modal.revalidate();
			modal.revalidateScroll();
			// The bank's outermost layer fills the box. It must not be re-laid out on its
			// own: the game then sizes it to the whole game window, which pushes the bank
			// out of view. Size it to the box directly if the box did not already.
			if (holder.getWidth() != modal.getWidth() || holder.getHeight() != modal.getHeight())
			{
				holder.setWidth(modal.getWidth());
				holder.setHeight(modal.getHeight());
			}
			window.revalidate();
			window.revalidateScroll();
			arrange(items, columns);
			appliedColumns = columns;
		}

		// Checked every frame, because the game and the Bank Tags plugin put tabs back whenever they like
		layoutTabRow(true);

		if (columns == DEFAULT_COLUMNS)
		{
			restoreModal();
			baseWindowWidth = -1;
			baseItemsWidth = -1;
		}
	}

	/**
	 * Lines everything tab-like up along the top, from the left: the Bank Tags plugin's
	 * new-tab button, the bank's own tabs, then Bank Tags' tag tabs, which normally run
	 * down the left side. Tag tabs that do not fit stay in their column.
	 */
	private void layoutTabRow(boolean inRow)
	{
		if (!inRow && !tabRowApplied)
		{
			return;
		}

		final Widget tabs = client.getWidget(InterfaceID.Bankmain.TABS);
		final Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (tabs == null || container == null)
		{
			return;
		}

		final Widget[] extras = container.getDynamicChildren();
		final boolean hasTagTabs = extras != null && extras.length >= TAG_TAB_FIRST_CHILD
			&& extras[TAG_TAB_FIRST_CHILD - 1] != null
			&& extras[TAG_TAB_FIRST_CHILD - 1].getOriginalWidth() == TAG_TAB_WIDTH;

		if (!inRow)
		{
			setPosition(tabs, WidgetPositionMode.ABSOLUTE_CENTER, 0, tabs.getOriginalY());
			if (hasTagTabs)
			{
				placeTagTabs(extras, container, Integer.MAX_VALUE);
			}
			tabRowApplied = false;
			return;
		}

		// The bank centres its tabs inside their strip, so move the strip rather than the
		// tabs. With Bank Tags, leave room for its new-tab button in the corner.
		int firstTabX = Integer.MAX_VALUE;
		int lastTabRight = 0;
		final Widget[] tabChildren = tabs.getDynamicChildren();
		for (int i = 0; tabChildren != null && i < tabChildren.length; i++)
		{
			final Widget child = tabChildren[i];
			if (child != null && !child.isSelfHidden())
			{
				firstTabX = Math.min(firstTabX, child.getOriginalX());
				lastTabRight = Math.max(lastTabRight, child.getOriginalX() + child.getOriginalWidth());
			}
		}
		if (firstTabX == Integer.MAX_VALUE)
		{
			return;
		}

		final int rowStart = hasTagTabs ? TAG_TAB_MARGIN + TAG_TAB_WIDTH + TAG_TAB_MARGIN : 0;
		final int stripX = rowStart - firstTabX;
		setPosition(tabs, WidgetPositionMode.ABSOLUTE_LEFT, stripX, tabs.getOriginalY());

		if (hasTagTabs)
		{
			placeTagTabs(extras, container, stripX + lastTabRight + TAG_TAB_MARGIN);
		}
		tabRowApplied = true;
	}

	/**
	 * Bank Tags keeps, after four controls, a background and an icon for each tag tab.
	 * Puts the ones it is currently showing in a row starting at rowX, or back in their
	 * column when rowX is past the edge of the bank.
	 */
	private void placeTagTabs(Widget[] extras, Widget container, int rowX)
	{
		final Widget scrollArea = extras[0];
		final int columnTop = scrollArea == null ? 0 : scrollArea.getOriginalY() + TAG_TAB_MARGIN;
		final int width = container.getWidth();

		int x = rowX;
		int shown = 0;
		boolean allInRow = true;
		for (int i = TAG_TAB_FIRST_CHILD; i + 1 < extras.length; i += 2)
		{
			final Widget background = extras[i];
			final Widget icon = extras[i + 1];
			if (background == null || icon == null)
			{
				break;
			}
			if (background.isSelfHidden())
			{
				// Scrolled out of view in Bank Tags' own list
				allInRow = false;
				continue;
			}

			if (x <= width - TAG_TAB_WIDTH)
			{
				setPosition(background, WidgetPositionMode.ABSOLUTE_LEFT, x, 0);
				setPosition(icon, WidgetPositionMode.ABSOLUTE_LEFT, x + TAG_ICON_INSET_X, TAG_ICON_INSET_Y);
				x += TAG_TAB_WIDTH + TAG_TAB_MARGIN;
			}
			else
			{
				final int y = columnTop + shown * (TAG_TAB_HEIGHT + TAG_TAB_MARGIN);
				setPosition(background, WidgetPositionMode.ABSOLUTE_LEFT, TAG_TAB_MARGIN, y);
				setPosition(icon, WidgetPositionMode.ABSOLUTE_LEFT, TAG_TAB_MARGIN + TAG_ICON_INSET_X, y + TAG_ICON_INSET_Y);
				allInRow = false;
			}
			shown++;
		}

		// The scroll arrows are only needed while some tag tabs are still in the column
		final boolean hideArrows = allInRow && rowX != Integer.MAX_VALUE;
		if (hideArrows || hidTagArrows)
		{
			for (int i = 1; i <= 2; i++)
			{
				if (extras[i] != null && extras[i].isSelfHidden() != hideArrows)
				{
					extras[i].setHidden(hideArrows);
				}
			}
			hidTagArrows = hideArrows;
		}
	}

	private static void setPosition(Widget widget, int xMode, int x, int y)
	{
		if (widget.getXPositionMode() == xMode && widget.getOriginalX() == x && widget.getOriginalY() == y)
		{
			return;
		}
		widget.setXPositionMode(xMode);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.revalidate();
	}

	/**
	 * Puts the bank back to its normal width, if it is loaded.
	 */
	void restore()
	{
		update(DEFAULT_COLUMNS);
		layoutTabRow(false);
		restoreModal();
		baseWindowWidth = -1;
		baseItemsWidth = -1;
		appliedColumns = DEFAULT_COLUMNS;
	}

	private void restoreModal()
	{
		if (modalWidget == null)
		{
			return;
		}

		if (client.getWidget(modalWidget.getId()) == modalWidget && modalWidget.getOriginalWidth() != baseModalWidth)
		{
			modalWidget.setOriginalWidth(baseModalWidth);
			modalWidget.revalidate();
			modalWidget.revalidateScroll();
		}
		modalWidget = null;
		baseModalWidth = -1;
	}

	/**
	 * Moves the item slots into rows of the given length. In the view of all tabs, each
	 * tab's items start on a new row under that tab's divider, and the dividers move up
	 * to close the rows that were saved.
	 */
	private void arrange(Widget items, int columns)
	{
		final Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		final List<Widget> visible = new ArrayList<>();
		for (Widget child : children)
		{
			if (child != null && !child.isSelfHidden())
			{
				visible.add(child);
			}
		}
		visible.sort(TOP_TO_BOTTOM);

		int shift = 0;
		boolean inSection = false;
		int column = 0;
		int rowY = 0;
		int lastOldY = 0;
		int lastNewY = -1;

		for (Widget widget : visible)
		{
			final int oldY = widget.getOriginalY();

			if (isItemSlot(widget))
			{
				if (!inSection)
				{
					inSection = true;
					column = 0;
					rowY = oldY + shift;
				}
				else if (column == columns)
				{
					column = 0;
					rowY += ROW_HEIGHT;
				}

				widget.setOriginalX(FIRST_COLUMN_X + column * COLUMN_SPACING);
				widget.setOriginalY(rowY);
				widget.revalidate();

				column++;
				lastOldY = oldY;
				lastNewY = rowY;
			}
			else
			{
				// Part of a divider between two tabs
				if (inSection)
				{
					inSection = false;
					shift = lastNewY - lastOldY;
				}
				// The game sizes the divider's line and label once, to the normal bank width
				final boolean spansGrid = widget.getOriginalHeight() == DIVIDER_LINE_HEIGHT
					|| widget.getOriginalHeight() == DIVIDER_LABEL_HEIGHT;
				final int width = spansGrid ? items.getOriginalWidth() - DIVIDER_SIDE_SPACE : widget.getOriginalWidth();
				if (shift != 0 || width != widget.getOriginalWidth())
				{
					widget.setOriginalY(oldY + shift);
					widget.setOriginalWidth(width);
					widget.revalidate();
				}
			}
		}

		updateScrolling(items, lastNewY == -1 ? 0 : lastNewY + SLOT_HEIGHT + SCROLL_PADDING);
	}

	private void updateScrolling(Widget items, int contentHeight)
	{
		final int viewHeight = items.getHeight();
		final boolean scrolls = contentHeight > viewHeight;
		final int scrollY = scrolls ? Math.min(items.getScrollY(), contentHeight - viewHeight) : 0;

		items.setScrollHeight(scrolls ? contentHeight : 0);
		items.setScrollY(scrollY);
		items.revalidateScroll();
		client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scrollY);
	}

	private static boolean isItemSlot(Widget widget)
	{
		return widget.getOriginalWidth() == SLOT_WIDTH && widget.getOriginalHeight() == SLOT_HEIGHT;
	}
}

package com.compassonly;

import java.awt.Rectangle;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Where the enlarged compass goes on the current frame, in canvas pixels.
 */
@Value
class CompassGeometry
{
	/** The space the hidden minimap occupied. */
	Rectangle minimapBounds;
	/** Sprite whose shape is the minimap's visible area, or -1. */
	int minimapMaskSprite;
	/** The space the game's own small compass occupied. */
	@Nullable
	Rectangle compassBounds;
	/** Sprite whose shape is the small compass's visible area, or -1. */
	int compassMaskSprite;

	double centerX;
	double centerY;
	/** Diameter of the enlarged compass. */
	double diameter;
	/** Diameter of the part of the compass sprite the game normally shows. */
	double sourceDiameter;
	/** Bigger than the minimap's space, so it is drawn over the interface instead of in the minimap's place. */
	boolean oversized;
	/** Where the shrunk minimap now sits, in the small compass's old spot, or null if it is hidden. */
	@Nullable
	Rectangle smallMinimapBounds;

	boolean contains(int x, int y)
	{
		final double dx = x - centerX;
		final double dy = y - centerY;
		final double radius = diameter / 2;
		return dx * dx + dy * dy <= radius * radius;
	}
}

package com.compassonly;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CompassOnlyConfig.GROUP)
public interface CompassOnlyConfig extends Config
{
	String GROUP = "compassonly";
	String HIDE_FRAME = "hideFrame";
	String MINIMAP_IN_COMPASS = "minimapInCompass";
	String BANK_COLUMNS = "bankColumns";
	int MIN_SIZE = 10;
	int MAX_SIZE = 1000;
	int MIN_INVENTORY_SIZE = 100;
	int MAX_INVENTORY_SIZE = 300;
	int MIN_BANK_SIZE = 100;
	int MAX_BANK_SIZE = 300;
	int MAX_BANK_COLUMNS = 24;

	@ConfigSection(
		name = "Compass",
		description = "The big compass and the small minimap",
		position = 0
	)
	String compassSection = "compass";

	@ConfigSection(
		name = "Side panel",
		description = "Enlarging the side panel, per tab",
		position = 1
	)
	String sidePanelSection = "sidePanel";

	@ConfigSection(
		name = "Bank",
		description = "Enlarging and widening the bank window",
		position = 2
	)
	String bankSection = "bank";

	// ---------------------------------------------------------------- Compass

	@ConfigItem(
		keyName = "showCompass",
		name = "Big compass",
		description = "Replace the minimap with an enlarged compass. Turn off to leave the minimap and compass as the game draws them.",
		position = 0,
		section = compassSection
	)
	default boolean showCompass()
	{
		return true;
	}

	@Range(min = MIN_SIZE, max = MAX_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "compassSize",
		name = "Compass size",
		description = "Size of the compass. 100% fills the minimap's space. Above 100% it grows past the minimap and is drawn on top of the interface.",
		position = 1,
		section = compassSection
	)
	default int compassSize()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "lookOptions",
		name = "Click to look north",
		description = "Left-click the compass to face north, right-click it for south, east and west",
		position = 2,
		section = compassSection
	)
	default boolean lookOptions()
	{
		return true;
	}

	@ConfigItem(
		keyName = MINIMAP_IN_COMPASS,
		name = "Small minimap",
		description = "Show the minimap, shrunk down, in the small circle where the game's compass used to be. It still works as normal: click to walk, scroll to zoom.",
		position = 3,
		section = compassSection
	)
	default boolean minimapInCompass()
	{
		return true;
	}

	@ConfigItem(
		keyName = HIDE_FRAME,
		name = "Hide minimap frame",
		description = "Also hide the stone frame around the minimap, leaving the orbs. Resizable layouts only.",
		position = 4,
		section = compassSection
	)
	default boolean hideFrame()
	{
		return false;
	}

	// ---------------------------------------------------------------- Side panel

	@Range(min = MIN_INVENTORY_SIZE, max = MAX_INVENTORY_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "inventorySize",
		name = "Inventory size",
		description = "Size of the side panel while the inventory is open. 100% is normal. Larger sizes grow up and to the left from its bottom-right corner, and everything in it can still be clicked, right-clicked and dragged.",
		position = 0,
		section = sidePanelSection
	)
	default int inventorySize()
	{
		return 100;
	}

	@Range(min = MIN_INVENTORY_SIZE, max = MAX_INVENTORY_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "prayerSize",
		name = "Prayer size",
		description = "Size of the side panel while the prayer tab is open. 100% is normal. Works like Inventory size.",
		position = 1,
		section = sidePanelSection
	)
	default int prayerSize()
	{
		return 100;
	}

	@Range(min = MIN_INVENTORY_SIZE, max = MAX_INVENTORY_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "combatSize",
		name = "Combat options size",
		description = "Size of the side panel while the combat options tab is open. 100% is normal. Works like Inventory size.",
		position = 2,
		section = sidePanelSection
	)
	default int combatSize()
	{
		return 100;
	}

	@Range(min = MIN_INVENTORY_SIZE, max = MAX_INVENTORY_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "equipmentSize",
		name = "Equipment size",
		description = "Size of the side panel while the equipment tab is open. 100% is normal. Works like Inventory size.",
		position = 3,
		section = sidePanelSection
	)
	default int equipmentSize()
	{
		return 100;
	}

	@Range(min = MIN_INVENTORY_SIZE, max = MAX_INVENTORY_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "spellbookSize",
		name = "Spellbook size",
		description = "Size of the side panel while the spellbook is open. 100% is normal. Works like Inventory size.",
		position = 4,
		section = sidePanelSection
	)
	default int spellbookSize()
	{
		return 100;
	}

	// ---------------------------------------------------------------- Bank

	@Range(min = MIN_BANK_SIZE, max = MAX_BANK_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "bankSize",
		name = "Bank size",
		description = "Size of the bank window. 100% is normal. Larger sizes grow outwards from its centre, as far as fits in the game window, and everything in it can still be clicked, dragged and scrolled.",
		position = 0,
		section = bankSection
	)
	default int bankSize()
	{
		return 100;
	}

	@Range(min = BankWidener.DEFAULT_COLUMNS, max = MAX_BANK_COLUMNS)
	@ConfigItem(
		keyName = BANK_COLUMNS,
		name = "Bank columns",
		description = "How many items the bank shows per row. 8 is normal. More columns make the bank window wider, up to what fits beside the side panel.",
		position = 1,
		section = bankSection
	)
	default int bankColumns()
	{
		return BankWidener.DEFAULT_COLUMNS;
	}
}

package com.compassonly;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.TexturePaint;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Paints the enlarged compass where the minimap used to be.
 *
 * Two of these are registered. The layered one is painted part-way through the game's own
 * interface drawing, at the point the minimap would have been painted, so the minimap frame
 * and the orbs end up on top of it exactly as they did with the minimap. The other is a
 * safety net that paints over the finished interface on any frame the layered one missed.
 */
class CompassOnlyOverlay extends Overlay
{
	private static final double JAU14_TO_RADIANS = Math.PI / 8192.0;

	// The game rotates the compass sprite about this pixel
	private static final double SPRITE_CENTER = 25.5;

	private static final Color OUTLINE_COLOR = new Color(20, 16, 10, 230);
	private static final double OUTLINE_WIDTH = 2;

	private static final double MIN_HOLE_COVERAGE = 0.4;
	private static final double MAX_HOLE_COVERAGE = 0.99;
	private static final int MASK_SIZE_TOLERANCE = 2;

	private final Client client;
	private final CompassOnlyPlugin compassPlugin;
	private final CompassOnlyConfig config;
	private final SpriteManager spriteManager;
	private final boolean layered;

	// Mask sprite id -> the hole it describes, or null if the sprite was not usable
	private final Map<Integer, Hole> holes = new HashMap<>();

	CompassOnlyOverlay(Client client, CompassOnlyPlugin plugin, CompassOnlyConfig config, SpriteManager spriteManager, boolean layered)
	{
		super(plugin);
		this.client = client;
		this.compassPlugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		this.layered = layered;

		setPosition(OverlayPosition.DYNAMIC);

		if (layered)
		{
			setLayer(OverlayLayer.MANUAL);
			// Resizable: the last piece drawn before the compass, the minimap and then the frame
			drawAfterLayer(InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_5);
			drawAfterLayer(InterfaceID.ToplevelPreEoc.MAP_NOCLICK_5);
			// Fixed: nothing usable comes before the frame, so go directly after it and before the orbs
			drawAfterLayer(InterfaceID.Toplevel.COMPASSCLICK);
		}
		else
		{
			setLayer(OverlayLayer.ABOVE_WIDGETS);
		}
	}

	@Override
	public String getName()
	{
		return layered ? "CompassOnlyOverlayLayered" : "CompassOnlyOverlayFallback";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final CompassGeometry geo = compassPlugin.getGeometry();
		if (geo == null || compassPlugin.isCompassDrawn())
		{
			return null;
		}

		// A compass bigger than the minimap's space would be cut off by the frame and orbs
		// drawn after it, so leave it to the pass that draws over the finished interface
		if (layered && geo.isOversized())
		{
			return null;
		}

		final BufferedImage sprite = spriteManager.getSprite(SpriteID.COMPASS, 0);
		if (sprite == null)
		{
			return null;
		}

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			draw(g, geo, sprite);
		}
		finally
		{
			g.dispose();
		}

		compassPlugin.setCompassDrawn(true);
		return null;
	}

	private void draw(Graphics2D g, CompassGeometry geo, BufferedImage sprite)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		if (!client.isResized())
		{
			prepareFixedMode(g, geo);
		}

		final double sourceRadius = geo.getSourceDiameter() / 2;
		final double scale = geo.getDiameter() / geo.getSourceDiameter();
		final double yaw = (client.getCameraYawTarget() & 0x3fff) * JAU14_TO_RADIANS;

		// From here on drawing is in compass sprite pixels, centred on the compass
		g.translate(geo.getCenterX(), geo.getCenterY());
		g.rotate(yaw);
		g.scale(scale, scale);

		final Ellipse2D dial = new Ellipse2D.Double(-sourceRadius, -sourceRadius, sourceRadius * 2, sourceRadius * 2);

		// The game treats the sprite as fully opaque, with its transparent pixels as black
		g.setColor(Color.BLACK);
		g.fill(dial);
		g.setPaint(new TexturePaint(sprite,
			new Rectangle2D.Double(-SPRITE_CENTER, -SPRITE_CENTER, sprite.getWidth(), sprite.getHeight())));
		g.fill(dial);

		// Keep the outline inside the dial so it never spills onto the minimap frame
		final double outlineWidth = OUTLINE_WIDTH / scale;
		final double outlineRadius = sourceRadius - outlineWidth / 2;
		g.setColor(OUTLINE_COLOR);
		g.setStroke(new BasicStroke((float) outlineWidth));
		g.draw(new Ellipse2D.Double(-outlineRadius, -outlineRadius, outlineRadius * 2, outlineRadius * 2));
	}

	/**
	 * In fixed mode the minimap and compass sit in holes cut out of the frame artwork, with
	 * nothing behind them. Once they are hidden those holes keep showing whatever was drawn
	 * there last, so paint them black, then confine the compass to the minimap's hole because
	 * here it is drawn on top of the frame rather than underneath it.
	 */
	private void prepareFixedMode(Graphics2D g, CompassGeometry geo)
	{
		final Rectangle minimapBounds = geo.getMinimapBounds();
		final Hole minimapHole = hole(geo.getMinimapMaskSprite(), minimapBounds);
		blackOut(g, minimapBounds, minimapHole);

		// When the minimap has moved into the compass's hole, that hole is in use
		final Rectangle compassBounds = geo.getCompassBounds();
		if (compassBounds != null && geo.getSmallMinimapBounds() == null)
		{
			blackOut(g, compassBounds, hole(geo.getCompassMaskSprite(), compassBounds));
		}

		if (minimapHole != null && !geo.isOversized())
		{
			g.translate(minimapBounds.x, minimapBounds.y);
			g.clip(minimapHole.shape);
			g.translate(-minimapBounds.x, -minimapBounds.y);
		}
	}

	private static void blackOut(Graphics2D g, Rectangle bounds, Hole hole)
	{
		if (hole != null)
		{
			g.drawImage(hole.image, bounds.x, bounds.y, null);
		}
		else
		{
			g.setColor(Color.BLACK);
			g.fill(new Ellipse2D.Double(bounds.x, bounds.y, bounds.width, bounds.height));
		}
	}

	/**
	 * The minimap and compass widgets each carry a mask sprite whose shape is exactly the
	 * hole they show through.
	 */
	private Hole hole(int maskSpriteId, Rectangle bounds)
	{
		if (maskSpriteId < 0)
		{
			return null;
		}
		if (holes.containsKey(maskSpriteId))
		{
			return holes.get(maskSpriteId);
		}

		final BufferedImage mask = spriteManager.getSprite(maskSpriteId, 0);
		if (mask == null)
		{
			// Not loaded yet, try again next frame
			return null;
		}

		final Hole hole = Hole.fromMask(mask, bounds);
		holes.put(maskSpriteId, hole);
		return hole;
	}

	private static final class Hole
	{
		/** The hole filled solid black on a transparent background. */
		private final BufferedImage image;
		/** The outline of the hole, relative to the top left of the mask. */
		private final Area shape;

		private Hole(BufferedImage image, Area shape)
		{
			this.image = image;
			this.shape = shape;
		}

		private static Hole fromMask(BufferedImage mask, Rectangle bounds)
		{
			final int width = mask.getWidth();
			final int height = mask.getHeight();
			if (Math.abs(width - bounds.width) > MASK_SIZE_TOLERANCE || Math.abs(height - bounds.height) > MASK_SIZE_TOLERANCE)
			{
				return null;
			}

			// The corner of the sprite is always outside the hole, whichever way round the
			// mask happens to be stored. Each row of the hole runs from its first inside
			// pixel to its last.
			final boolean outsideIsOpaque = isOpaque(mask.getRGB(0, 0));
			final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			final Area shape = new Area();
			int covered = 0;

			for (int y = 0; y < height; y++)
			{
				int first = -1;
				int last = -1;
				for (int x = 0; x < width; x++)
				{
					if (isOpaque(mask.getRGB(x, y)) != outsideIsOpaque)
					{
						if (first == -1)
						{
							first = x;
						}
						last = x;
					}
				}

				if (first == -1)
				{
					continue;
				}

				final int length = last - first + 1;
				for (int x = first; x <= last; x++)
				{
					image.setRGB(x, y, 0xFF000000);
				}
				shape.add(new Area(new Rectangle(first, y, length, 1)));
				covered += length;
			}

			final double coverage = (double) covered / (width * height);
			if (coverage < MIN_HOLE_COVERAGE || coverage > MAX_HOLE_COVERAGE)
			{
				return null;
			}

			return new Hole(image, shape);
		}

		private static boolean isOpaque(int argb)
		{
			return (argb >>> 24) != 0;
		}
	}
}

package com.compassonly;

import com.google.inject.Provides;
import java.awt.Rectangle;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Compass Only",
	description = "Big compass in place of the minimap, plus bigger side panels and a bigger, wider bank",
	tags = {"minimap", "compass", "hide", "hud", "immersion", "inventory", "prayer", "spellbook", "equipment", "bank", "scale", "resize", "zoom", "ui"}
)
public class CompassOnlyPlugin extends Plugin
{
	// The game marks the widgets it paints the minimap and the compass into with these
	private static final int CONTENT_TYPE_MINIMAP = 1338;
	private static final int CONTENT_TYPE_COMPASS = 1339;

	// Fixed, resizable classic and resizable modern
	private static final int[] LAYOUTS = {
		InterfaceID.TOPLEVEL,
		InterfaceID.TOPLEVEL_OSRS_STRETCH,
		InterfaceID.TOPLEVEL_PRE_EOC
	};

	private static final int MAX_COMPONENTS = 400;
	private static final int MAX_DEPTH = 32;
	private static final double DEFAULT_SOURCE_DIAMETER = 33;
	private static final int MIN_SIZE_PERCENT = CompassOnlyConfig.MIN_SIZE;
	private static final int MAX_SIZE_PERCENT = CompassOnlyConfig.MAX_SIZE;

	// Camera yaw is measured in 1/16384ths of a turn, increasing anticlockwise from north
	private static final int YAW_NORTH = 0;
	private static final int YAW_WEST = 4096;
	private static final int YAW_SOUTH = 8192;
	private static final int YAW_EAST = 12288;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CompassOnlyConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private TooltipManager tooltipManager;

	@Inject
	private RuneLiteConfig runeLiteConfig;

	// Whether the minimap and compass have been changed and need putting back
	private boolean compassActive;

	private CompassOnlyOverlay layeredOverlay;
	private CompassOnlyOverlay fallbackOverlay;
	private InventoryScaleOverlay inventoryOverlay;
	private InventoryMouseMapper inventoryMouseMapper;
	private BankWidener bankWidener;

	/**
	 * Where the real and the enlarged inventory are, or null if it is not being enlarged.
	 * Read by the mouse mapper on the input thread, so replaced whole rather than changed.
	 */
	@Getter(AccessLevel.PACKAGE)
	private volatile InventoryGeometry inventoryGeometry;

	// The menu the game built for the real panel last frame, while the mouse was over its copy
	private SavedMenuEntry[] copyMenu;

	// Everything below is only touched on the client thread
	private int partsLayout = -1;
	private MinimapParts parts = new MinimapParts();
	// Every minimap widget moved into a compass spot, across all layouts, with how it was before
	private final Map<Widget, SavedLayout> movedMinimaps = new IdentityHashMap<>();

	/**
	 * Where the compass belongs on the frame being drawn, or null if it should not be drawn.
	 */
	@Getter(AccessLevel.PACKAGE)
	private CompassGeometry geometry;

	/**
	 * Whether the compass has been painted on the frame being drawn. Outside of rendering
	 * this still holds the answer for the last frame.
	 */
	@Getter(AccessLevel.PACKAGE)
	@Setter(AccessLevel.PACKAGE)
	private boolean compassDrawn;

	@Provides
	CompassOnlyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompassOnlyConfig.class);
	}

	@Override
	protected void startUp()
	{
		layeredOverlay = new CompassOnlyOverlay(client, this, config, spriteManager, true);
		fallbackOverlay = new CompassOnlyOverlay(client, this, config, spriteManager, false);
		overlayManager.add(layeredOverlay);
		overlayManager.add(fallbackOverlay);

		bankWidener = new BankWidener(client);
		inventoryMouseMapper = new InventoryMouseMapper(client, this);
		inventoryOverlay = new InventoryScaleOverlay(client, this, inventoryMouseMapper, tooltipManager, runeLiteConfig);
		overlayManager.add(inventoryOverlay);
		mouseManager.registerMouseListener(inventoryMouseMapper);
		eventBus.register(copyMenuRecorder);
		mouseManager.registerMouseWheelListener(inventoryMouseMapper);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(layeredOverlay);
		overlayManager.remove(fallbackOverlay);
		layeredOverlay = null;
		fallbackOverlay = null;

		inventoryGeometry = null;
		eventBus.unregister(copyMenuRecorder);
		copyMenu = null;
		mouseManager.unregisterMouseListener(inventoryMouseMapper);
		mouseManager.unregisterMouseWheelListener(inventoryMouseMapper);
		overlayManager.remove(inventoryOverlay);
		inventoryMouseMapper = null;
		inventoryOverlay = null;

		final BankWidener widener = bankWidener;
		bankWidener = null;
		clientThread.invoke(widener::restore);
		clientThread.invoke(this::restoreWidgets);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CompassOnlyConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (CompassOnlyConfig.MINIMAP_IN_COMPASS.equals(event.getKey()) && !config.minimapInCompass())
		{
			clientThread.invoke(this::restoreAllMovedMinimaps);
		}
		else if (CompassOnlyConfig.HIDE_FRAME.equals(event.getKey()) && !config.hideFrame())
		{
			clientThread.invoke(() ->
			{
				for (int layout : LAYOUTS)
				{
					show(findParts(layout).frame);
				}
			});
		}
	}

	/**
	 * The game's scripts un-hide interface pieces whenever they rebuild the layout, so the
	 * minimap is re-hidden right before every frame rather than once.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		compassDrawn = false;
		geometry = null;

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			inventoryGeometry = null;
			return;
		}

		// Widen the bank first, so its enlarged copy is sized from the widened window
		bankWidener.update(config.bankColumns());

		// The bank hides the normal inventory while it is open, so only one is ever enlarged
		final InventoryGeometry bank = computeBankGeometry();
		inventoryGeometry = bank != null ? bank : computeSidePanelGeometry();

		if (!config.showCompass())
		{
			if (compassActive)
			{
				restoreWidgets();
				compassActive = false;
			}
			return;
		}
		compassActive = true;

		locateParts();
		if (parts.minimap == null)
		{
			return;
		}

		hide(parts.compass);
		if (config.hideFrame())
		{
			hide(parts.frame);
		}

		final boolean swap = config.minimapInCompass() && canSwap();
		if (swap)
		{
			moveMinimapIntoCompassSpot();
			// The game's compass click area sits on top of that spot and would swallow
			// clicks meant for the minimap. The big compass has the same options.
			hide(parts.compassClick);
		}
		else
		{
			restoreMinimap(parts.minimap);
			hide(parts.minimap);
			show(parts.compassClick);
		}

		geometry = computeGeometry(swap);
	}

	/**
	 * Enlarges the whole side panel, frame and all, while a tab with a size setting is
	 * open. It grows from the panel's bottom-right corner, which sits against the edge of
	 * the window in every layout, and is kept inside the window.
	 */
	private InventoryGeometry computeSidePanelGeometry()
	{
		final int percent = openTabSize();
		if (percent <= CompassOnlyConfig.MIN_INVENTORY_SIZE)
		{
			return null;
		}

		final Rectangle source = sidePanelBounds();
		if (source == null || source.isEmpty())
		{
			return null;
		}

		final double scale = Math.min(percent, CompassOnlyConfig.MAX_INVENTORY_SIZE) / 100.0;
		final int width = (int) Math.round(source.width * scale);
		final int height = (int) Math.round(source.height * scale);
		final int x = Math.max(0, source.x + source.width - width);
		final int y = Math.max(0, source.y + source.height - height);
		return new InventoryGeometry(source, new Rectangle(x, y, width, height));
	}

	/**
	 * The size setting for the side tab that is open, or 100 if it has none. Each tab is
	 * its own interface, hidden while another tab is open. The bank shows its own copy
	 * of the inventory, so the inventory tab counts as closed while the bank is open.
	 */
	private int openTabSize()
	{
		if (isOpen(InterfaceID.Inventory.ITEMS))
		{
			return config.inventorySize();
		}
		if (isOpen(InterfaceID.PRAYERBOOK << 16))
		{
			return config.prayerSize();
		}
		if (isOpen(InterfaceID.COMBAT_INTERFACE << 16))
		{
			return config.combatSize();
		}
		if (isOpen(InterfaceID.WORNITEMS << 16))
		{
			return config.equipmentSize();
		}
		if (isOpen(InterfaceID.MAGIC_SPELLBOOK << 16))
		{
			return config.spellbookSize();
		}
		return CompassOnlyConfig.MIN_INVENTORY_SIZE;
	}

	private boolean isOpen(int componentId)
	{
		final Widget widget = client.getWidget(componentId);
		return widget != null && !widget.isHidden();
	}

	/**
	 * The side panel with its stone frame, in canvas pixels. In the classic layouts that
	 * includes the rows of tab buttons, so those are enlarged and clickable too.
	 */
	private Rectangle sidePanelBounds()
	{
		switch (client.getTopLevelInterfaceId())
		{
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return visibleBounds(InterfaceID.ToplevelOsrsStretch.SIDE_MENU);
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return visibleBounds(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER);
			case InterfaceID.TOPLEVEL:
			{
				final Rectangle panel = visibleBounds(InterfaceID.Toplevel.SIDE);
				final Rectangle top = visibleBounds(InterfaceID.Toplevel.SIDE_TOP_CONTAINER);
				final Rectangle bottom = visibleBounds(InterfaceID.Toplevel.SIDE_BOTTOM_CONTAINER);
				if (panel == null || top == null || bottom == null)
				{
					return null;
				}
				return panel.union(top).union(bottom);
			}
			default:
				return null;
		}
	}

	private Rectangle visibleBounds(int componentId)
	{
		final Widget widget = client.getWidget(componentId);
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		final Rectangle bounds = widget.getBounds();
		return bounds == null || bounds.isEmpty() ? null : new Rectangle(bounds);
	}

	/**
	 * Grows the bank window outwards from its centre, by as much as fits in the game window.
	 */
	private InventoryGeometry computeBankGeometry()
	{
		final int percent = config.bankSize();
		if (percent <= CompassOnlyConfig.MIN_BANK_SIZE)
		{
			return null;
		}

		final Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden())
		{
			return null;
		}

		final Rectangle source = bank.getBounds();
		if (source == null || source.isEmpty())
		{
			return null;
		}

		final int canvasWidth = client.getCanvasWidth();
		final int canvasHeight = client.getCanvasHeight();
		double scale = Math.min(percent, CompassOnlyConfig.MAX_BANK_SIZE) / 100.0;
		scale = Math.min(scale, Math.min((double) canvasWidth / source.width, (double) canvasHeight / source.height));
		if (scale <= 1)
		{
			return null;
		}

		final int width = (int) Math.round(source.width * scale);
		final int height = (int) Math.round(source.height * scale);
		final int x = (int) clamp(source.getCenterX() - width / 2.0, 0, canvasWidth - width);
		final int y = (int) clamp(source.getCenterY() - height / 2.0, 0, canvasHeight - height);
		return new InventoryGeometry(new Rectangle(source), new Rectangle(x, y, width, height));
	}

	/**
	 * The minimap can only take over the compass's spot if both live in the same
	 * container, so the compass's position means the same thing for the minimap.
	 */
	private boolean canSwap()
	{
		return parts.compass != null
			&& parts.compass.getParentId() == parts.minimap.getParentId()
			&& parts.compass.getWidth() > 0
			&& parts.compass.getHeight() > 0;
	}

	/**
	 * Moves the game's own minimap into the small compass's hole and shrinks it to fit,
	 * so it keeps everything the real minimap does: dots, click to walk, scroll to zoom.
	 * Its shape comes from the widget's mask sprite, so it takes the compass's mask too.
	 */
	private void moveMinimapIntoCompassSpot()
	{
		final Widget minimap = parts.minimap;
		final Widget compass = parts.compass;

		if (!movedMinimaps.containsKey(minimap))
		{
			movedMinimaps.put(minimap, SavedLayout.of(minimap));
		}

		show(minimap);

		final int x = compass.getRelativeX();
		final int y = compass.getRelativeY();
		final int width = compass.getWidth();
		final int height = compass.getHeight();
		final int mask = compass.getSpriteId();

		if (minimap.getRelativeX() == x && minimap.getRelativeY() == y
			&& minimap.getWidth() == width && minimap.getHeight() == height
			&& minimap.getSpriteId() == mask)
		{
			return;
		}

		minimap.setWidthMode(WidgetSizeMode.ABSOLUTE);
		minimap.setHeightMode(WidgetSizeMode.ABSOLUTE);
		minimap.setOriginalWidth(width);
		minimap.setOriginalHeight(height);
		minimap.setSpriteId(mask);
		// Unlike a normal position, a forced one survives the game re-laying out the interface
		minimap.setForcedPosition(x, y);
		minimap.revalidate();
	}

	private void restoreMinimap(Widget minimap)
	{
		final SavedLayout saved = movedMinimaps.remove(minimap);
		if (saved != null)
		{
			saved.applyTo(minimap);
		}
	}

	private void restoreAllMovedMinimaps()
	{
		movedMinimaps.forEach((widget, saved) -> saved.applyTo(widget));
		movedMinimaps.clear();
	}

	/**
	 * Gives the enlarged compass the same click options as the game's own compass.
	 */
	/**
	 * While the mouse is over an enlarged panel, the game is told it is over the real one,
	 * so the menu it builds each frame has the options for what is under the mouse there:
	 * Use, Drop, Eat and so on. Keep a copy, made after other plugins have changed the menu.
	 */
	private final Object copyMenuRecorder = new Object()
	{
		// RuneLite allows one handler per event per object, named after the event, so
		// this runs on its own to get its own, late, place in the order
		@Subscribe(priority = -100)
		public void onPostMenuSort(PostMenuSort event)
		{
			final InventoryMouseMapper mapper = inventoryMouseMapper;
			// After a right-click on the copy the game rebuilds the menu for whatever is
			// behind it, so keep the copy made before the click
			if (mapper == null || client.isMenuOpen() || mapper.isRightClickPending())
			{
				return;
			}
			copyMenu = mapper.getMappedFrom() != null ? SavedMenuEntry.copyOf(client.getMenu().getMenuEntries()) : null;
		}
	};

	/**
	 * A right-click on an enlarged panel is passed to the game where it really happened, so
	 * the menu opens at the cursor. The game fills that menu for whatever is behind the
	 * enlarged panel, so put back the options for what was under the mouse on the real one.
	 */
	@Subscribe(priority = 100)
	public void onMenuOpened(MenuOpened event)
	{
		final InventoryMouseMapper mapper = inventoryMouseMapper;
		final SavedMenuEntry[] saved = copyMenu;
		if (mapper == null || !mapper.takeRightClickOnCopy() || saved == null || saved.length == 0)
		{
			return;
		}

		final Menu menu = client.getMenu();
		SavedMenuEntry.restoreInto(menu, saved);
		event.setMenuEntries(menu.getMenuEntries());
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		final CompassGeometry geo = geometry;
		if (geo == null || !compassDrawn || !config.lookOptions()
			|| client.isMenuOpen() || client.isWidgetSelected())
		{
			return;
		}

		final Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !geo.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		// The small minimap overlaps the edge of the compass, and clicks there are for walking
		final Rectangle smallMinimap = geo.getSmallMinimapBounds();
		if (smallMinimap != null && smallMinimap.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		// Leave the menu alone if the mouse is over something of its own, such as an
		// orb or a window that happens to sit on top of the compass
		final Menu menu = client.getMenu();
		final MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length > 0)
		{
			final MenuAction top = entries[entries.length - 1].getType();
			if (top != MenuAction.CANCEL && top != MenuAction.WALK)
			{
				return;
			}
		}

		// Each entry is added above the previous one, and the topmost is the left-click action
		addLookOption(menu, "Look West", YAW_WEST);
		addLookOption(menu, "Look East", YAW_EAST);
		addLookOption(menu, "Look South", YAW_SOUTH);
		addLookOption(menu, "Look North", YAW_NORTH);
	}

	private void addLookOption(Menu menu, String option, int yaw)
	{
		menu.createMenuEntry(-1)
			.setOption(option)
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> client.setCameraYawTarget(yaw));
	}

	private void locateParts()
	{
		final int layout = client.getTopLevelInterfaceId();
		if (layout == partsLayout && isCurrent(parts.minimap))
		{
			return;
		}

		partsLayout = layout;
		parts = findParts(layout);

		// Widgets replaced by an interface reload are gone, so there is nothing to put back
		movedMinimaps.keySet().removeIf(widget -> !isCurrent(widget));
	}

	/**
	 * Widgets are rebuilt when an interface reloads, which leaves old references pointing at nothing.
	 */
	private boolean isCurrent(Widget widget)
	{
		return widget != null && client.getWidget(widget.getId()) == widget;
	}

	/**
	 * Finds the minimap pieces by what they are rather than by component id, so a game
	 * update that renumbers the interface does not make the plugin hide the wrong thing.
	 */
	private MinimapParts findParts(int layout)
	{
		final MinimapParts found = new MinimapParts();
		if (layout < 0)
		{
			return found;
		}

		for (int child = 0; child < MAX_COMPONENTS; child++)
		{
			final Widget widget = client.getWidget(layout, child);
			if (widget == null)
			{
				continue;
			}

			final int contentType = widget.getContentType();
			if (contentType == CONTENT_TYPE_MINIMAP)
			{
				found.minimap = widget;
			}
			else if (contentType == CONTENT_TYPE_COMPASS)
			{
				found.compass = widget;
			}
			else if (widget.getSpriteId() == SpriteID.OSRS_STRETCH_MAPSURROUND)
			{
				found.frame = widget;
			}
		}

		if (found.frame != null
			&& (found.minimap == null || found.frame.getParentId() != found.minimap.getParentId()))
		{
			found.frame = null;
		}

		found.compassClick = client.getWidget(compassClickId(layout));

		return found;
	}

	private static int compassClickId(int layout)
	{
		switch (layout)
		{
			case InterfaceID.TOPLEVEL:
				return InterfaceID.Toplevel.COMPASSCLICK;
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return InterfaceID.ToplevelOsrsStretch.COMPASSCLICK;
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return InterfaceID.ToplevelPreEoc.COMPASSCLICK;
			default:
				return -1;
		}
	}

	private CompassGeometry computeGeometry(boolean swapped)
	{
		final Widget minimap = parts.minimap;

		// If the game's own setting or another plugin has hidden the whole minimap block,
		// orbs get rearranged into this space, so stay out of the way
		final Widget container = minimap.getParent();
		if (container == null || container.isHidden())
		{
			return null;
		}

		// The big compass goes where the minimap normally is, not where it has been moved to
		final SavedLayout saved = movedMinimaps.get(minimap);
		final Rectangle minimapBounds = saved != null ? saved.homeBounds(minimap) : canvasBounds(minimap);
		final int minimapMask = saved != null ? saved.spriteId : minimap.getSpriteId();
		if (minimapBounds.isEmpty())
		{
			return null;
		}

		Rectangle compassBounds = null;
		int compassMask = -1;
		double sourceDiameter = DEFAULT_SOURCE_DIAMETER;
		if (parts.compass != null)
		{
			compassBounds = canvasBounds(parts.compass);
			compassMask = parts.compass.getSpriteId();
			if (!compassBounds.isEmpty())
			{
				sourceDiameter = Math.min(compassBounds.width, compassBounds.height);
			}
		}

		final int sizePercent = Math.max(MIN_SIZE_PERCENT, Math.min(MAX_SIZE_PERCENT, config.compassSize()));
		final boolean oversized = sizePercent > 100;
		double diameter = Math.min(minimapBounds.width, minimapBounds.height) * sizePercent / 100.0;
		double centerX = minimapBounds.getCenterX();
		double centerY = minimapBounds.getCenterY();

		if (oversized)
		{
			// Grow from the minimap's centre, but slide back inwards so none of it is
			// pushed off the edge of the game window
			final int canvasWidth = client.getCanvasWidth();
			final int canvasHeight = client.getCanvasHeight();
			diameter = Math.min(diameter, Math.min(canvasWidth, canvasHeight));
			final double radius = diameter / 2;
			centerX = clamp(centerX, radius, canvasWidth - radius);
			centerY = clamp(centerY, radius, canvasHeight - radius);
		}

		return new CompassGeometry(
			minimapBounds,
			minimapMask,
			compassBounds,
			compassMask,
			centerX,
			centerY,
			diameter,
			sourceDiameter,
			oversized,
			swapped ? canvasBounds(minimap) : null);
	}

	private static double clamp(double value, double min, double max)
	{
		return max < min ? (min + max) / 2 : Math.max(min, Math.min(max, value));
	}

	/**
	 * A hidden widget's reported canvas location goes stale because the game only updates it
	 * while drawing, so add up the offset within each parent instead.
	 */
	private static Rectangle canvasBounds(Widget widget)
	{
		int x = 0;
		int y = 0;
		Widget current = widget;
		for (int depth = 0; current != null && depth < MAX_DEPTH; depth++)
		{
			x += current.getRelativeX();
			y += current.getRelativeY();
			current = current.getParent();
		}
		return new Rectangle(x, y, widget.getWidth(), widget.getHeight());
	}

	private void restoreWidgets()
	{
		// A layout that was used earlier stays loaded with its pieces still hidden, so
		// restore all of them and not only the one on screen
		for (int layout : LAYOUTS)
		{
			restore(findParts(layout));
		}
		restore(parts);
		restoreAllMovedMinimaps();

		parts = new MinimapParts();
		partsLayout = -1;
		geometry = null;
		compassDrawn = false;
	}

	private static void restore(MinimapParts target)
	{
		show(target.minimap);
		show(target.compass);
		show(target.frame);
		show(target.compassClick);
	}

	private static void hide(Widget widget)
	{
		if (widget != null && !widget.isSelfHidden())
		{
			widget.setHidden(true);
		}
	}

	private static void show(Widget widget)
	{
		if (widget != null && widget.isSelfHidden())
		{
			widget.setHidden(false);
		}
	}

	private static final class MinimapParts
	{
		private Widget minimap;
		private Widget compass;
		private Widget frame;
		private Widget compassClick;
	}

	/**
	 * How a minimap widget was laid out before it was moved, so it can be put back.
	 */
	private static final class SavedLayout
	{
		private final int originalX;
		private final int originalY;
		private final int originalWidth;
		private final int originalHeight;
		private final int xMode;
		private final int yMode;
		private final int widthMode;
		private final int heightMode;
		private final int spriteId;

		private SavedLayout(Widget widget)
		{
			originalX = widget.getOriginalX();
			originalY = widget.getOriginalY();
			originalWidth = widget.getOriginalWidth();
			originalHeight = widget.getOriginalHeight();
			xMode = widget.getXPositionMode();
			yMode = widget.getYPositionMode();
			widthMode = widget.getWidthMode();
			heightMode = widget.getHeightMode();
			spriteId = widget.getSpriteId();
		}

		static SavedLayout of(Widget widget)
		{
			return new SavedLayout(widget);
		}

		void applyTo(Widget widget)
		{
			widget.setForcedPosition(-1, -1);
			widget.setWidthMode(widthMode);
			widget.setHeightMode(heightMode);
			widget.setOriginalWidth(originalWidth);
			widget.setOriginalHeight(originalHeight);
			widget.setXPositionMode(xMode);
			widget.setYPositionMode(yMode);
			widget.setOriginalX(originalX);
			widget.setOriginalY(originalY);
			widget.setSpriteId(spriteId);
			widget.revalidate();
		}

		/**
		 * Where the widget would be on the canvas if it had not been moved, worked out from
		 * its original layout and its container's current size.
		 */
		Rectangle homeBounds(Widget widget)
		{
			final Widget parent = widget.getParent();
			if (parent == null || widthMode != WidgetSizeMode.ABSOLUTE || heightMode != WidgetSizeMode.ABSOLUTE)
			{
				return new Rectangle();
			}

			final Rectangle parentBounds = canvasBounds(parent);
			final int x = position(xMode, originalX, parentBounds.width, originalWidth);
			final int y = position(yMode, originalY, parentBounds.height, originalHeight);
			return new Rectangle(parentBounds.x + x, parentBounds.y + y, originalWidth, originalHeight);
		}

		private static int position(int mode, int offset, int parentSize, int size)
		{
			switch (mode)
			{
				case WidgetPositionMode.ABSOLUTE_CENTER:
					return (parentSize - size) / 2 + offset;
				case WidgetPositionMode.ABSOLUTE_RIGHT:
					return parentSize - size - offset;
				default:
					return offset;
			}
		}
	}
}

package com.compassonly;

import java.awt.Rectangle;
import lombok.Value;

/**
 * Where the real inventory is and where its enlarged copy is drawn, in canvas pixels.
 */
@Value
class InventoryGeometry
{
	/** The real inventory, drawn by the game at normal size. */
	Rectangle source;
	/** The enlarged copy drawn on top. */
	Rectangle target;

	int toSourceX(int x)
	{
		return source.x + (int) ((long) (x - target.x) * source.width / target.width);
	}

	int toSourceY(int y)
	{
		return source.y + (int) ((long) (y - target.y) * source.height / target.height);
	}
}

package com.compassonly;

import java.awt.Component;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Makes the enlarged inventory clickable by moving the mouse, as far as the game can
 * tell, onto the matching spot of the real inventory underneath.
 *
 * Right-clicks are left where they are. The game builds the right-click menu from what
 * the mouse was last over, which is already the right item, and opens it where the
 * right-click happened, so the menu appears at the cursor and not over the small
 * inventory. While a menu is open nothing is moved, so its options can be clicked.
 */
class InventoryMouseMapper extends MouseAdapter implements MouseWheelListener
{
	private final Client client;
	private final CompassOnlyPlugin plugin;

	// Set while a left-button press that started on the enlarged inventory is held, so a
	// dragged item keeps following the mouse even if it leaves the enlarged area
	private boolean holding;

	// Where the mouse really is, while it is being mapped onto the real inventory
	private volatile java.awt.Point mappedFrom;

	// When a right-click on the enlarged copy happened, until the menu it opens has been
	// fixed up. A menu opens within a frame or two, so an old one is ignored.
	private static final long RIGHT_CLICK_WINDOW_MS = 1000;
	private volatile long rightClickedCopyAt;

	InventoryMouseMapper(Client client, CompassOnlyPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (event.getButton() == MouseEvent.BUTTON3)
		{
			// Left where it is so the menu opens at the cursor. The plugin then swaps in
			// the options for what the mouse was over on the real panel.
			rightClickedCopyAt = mappable(event) != null ? System.currentTimeMillis() : 0;
			return event;
		}
		rightClickedCopyAt = 0;

		final InventoryGeometry geo = mappable(event);
		if (geo == null)
		{
			return event;
		}

		holding = true;
		return map(event, geo);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (event.getButton() == MouseEvent.BUTTON3)
		{
			return event;
		}

		final InventoryGeometry geo = plugin.getInventoryGeometry();
		if (holding)
		{
			holding = false;
			return geo != null ? map(event, geo) : event;
		}

		final InventoryGeometry inside = mappable(event);
		return inside != null ? map(event, inside) : event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (event.getButton() == MouseEvent.BUTTON3)
		{
			return event;
		}

		final InventoryGeometry geo = mappable(event);
		return geo != null ? map(event, geo) : event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		final MouseEvent result = mouseDraggedMapped(event);
		mappedFrom = result != event ? event.getPoint() : null;
		return result;
	}

	private MouseEvent mouseDraggedMapped(MouseEvent event)
	{
		if (SwingUtilities.isRightMouseButton(event))
		{
			return event;
		}

		final InventoryGeometry geo = plugin.getInventoryGeometry();
		if (geo == null)
		{
			holding = false;
			return event;
		}

		if (holding || geo.getTarget().contains(event.getX(), event.getY()))
		{
			return map(event, geo);
		}
		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		holding = false;
		final InventoryGeometry geo = mappable(event);
		mappedFrom = geo != null ? event.getPoint() : null;
		return geo != null ? map(event, geo) : event;
	}

	/**
	 * Whether the menu being opened came from a right-click on the enlarged copy. Answers
	 * once per right-click.
	 */
	boolean takeRightClickOnCopy()
	{
		final boolean was = isRightClickPending();
		rightClickedCopyAt = 0;
		return was;
	}

	/**
	 * Whether a right-click on the enlarged copy is waiting for its menu to open. Until
	 * then the game sees the mouse where the click really was, over whatever is behind.
	 */
	boolean isRightClickPending()
	{
		final long at = rightClickedCopyAt;
		return at != 0 && System.currentTimeMillis() - at < RIGHT_CLICK_WINDOW_MS;
	}

	/**
	 * Where the mouse really is, if it is currently over the enlarged copy, or null.
	 */
	java.awt.Point getMappedFrom()
	{
		return plugin.getInventoryGeometry() != null ? mappedFrom : null;
	}

	/**
	 * Scrolling, so the bank scrolls when the wheel is used anywhere over its enlarged copy.
	 */
	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		final InventoryGeometry geo = mappable(event);
		if (geo == null)
		{
			return event;
		}

		return new MouseWheelEvent((Component) event.getSource(), event.getID(), event.getWhen(),
			event.getModifiersEx(), mapX(event, geo), mapY(event, geo), event.getXOnScreen(), event.getYOnScreen(),
			event.getClickCount(), event.isPopupTrigger(), event.getScrollType(), event.getScrollAmount(),
			event.getWheelRotation(), event.getPreciseWheelRotation());
	}

	/**
	 * The current layout, if this event is over the enlarged inventory and should be moved.
	 */
	private InventoryGeometry mappable(MouseEvent event)
	{
		final InventoryGeometry geo = plugin.getInventoryGeometry();
		if (geo == null || client.isMenuOpen())
		{
			return null;
		}
		return geo.getTarget().contains(event.getX(), event.getY()) ? geo : null;
	}

	private static MouseEvent map(MouseEvent event, InventoryGeometry geo)
	{
		return new MouseEvent((Component) event.getSource(), event.getID(), event.getWhen(),
			event.getModifiersEx(), mapX(event, geo), mapY(event, geo), event.getClickCount(), event.isPopupTrigger(), event.getButton());
	}

	// Clamped so a drag that leaves the enlarged area stays at the edge of the real one
	private static int mapX(MouseEvent event, InventoryGeometry geo)
	{
		return clamp(geo.toSourceX(event.getX()), geo.getSource().x, geo.getSource().x + geo.getSource().width - 1);
	}

	private static int mapY(MouseEvent event, InventoryGeometry geo)
	{
		return clamp(geo.toSourceY(event.getY()), geo.getSource().y, geo.getSource().y + geo.getSource().height - 1);
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.compassonly;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.List;
import net.runelite.api.BufferProvider;
import net.runelite.api.Client;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.config.TooltipPositionType;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws the inventory enlarged. It copies the pixels the game has just drawn for the
 * inventory and scales them up, so everything shown there carries over: item counts,
 * the selected item, an item being dragged, and other plugins' markings.
 *
 * This is drawn right after the game's interface and before the right-click menu,
 * so menus still appear on top of it.
 *
 * Over the enlarged copy the game believes the mouse is over the real, smaller panel,
 * so RuneLite would draw tooltips there. This draws them at the real cursor instead.
 */
class InventoryScaleOverlay extends Overlay
{
	private final Client client;
	private final CompassOnlyPlugin compassPlugin;
	// Matches RuneLite's own tooltip placement
	private static final int TOOLTIP_UNDER_OFFSET = 24;
	private static final int TOOLTIP_PADDING = 2;

	private final InventoryMouseMapper mouseMapper;
	private final TooltipManager tooltipManager;
	private final RuneLiteConfig runeLiteConfig;

	private BufferedImage copy;
	private int tooltipWidth;
	private int tooltipHeight;

	InventoryScaleOverlay(Client client, CompassOnlyPlugin plugin, InventoryMouseMapper mouseMapper,
		TooltipManager tooltipManager, RuneLiteConfig runeLiteConfig)
	{
		super(plugin);
		this.client = client;
		this.compassPlugin = plugin;
		this.mouseMapper = mouseMapper;
		this.tooltipManager = tooltipManager;
		this.runeLiteConfig = runeLiteConfig;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Among dynamic overlays a higher priority is drawn later, so other plugins'
		// inventory markings are in place before the copy is taken
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final InventoryGeometry geo = compassPlugin.getInventoryGeometry();
		if (geo == null)
		{
			return null;
		}

		final BufferProvider buffer = client.getBufferProvider();
		if (buffer == null)
		{
			return null;
		}

		final Rectangle source = geo.getSource();
		final int bufferWidth = buffer.getWidth();
		if (source.x < 0 || source.y < 0
			|| source.x + source.width > bufferWidth
			|| source.y + source.height > buffer.getHeight())
		{
			return null;
		}

		if (copy == null || copy.getWidth() != source.width || copy.getHeight() != source.height)
		{
			copy = new BufferedImage(source.width, source.height, BufferedImage.TYPE_INT_RGB);
		}

		// Copy first: the enlarged image is drawn over the same pixels it is read from
		final int[] pixels = buffer.getPixels();
		final int[] copyPixels = ((DataBufferInt) copy.getRaster().getDataBuffer()).getData();
		for (int row = 0; row < source.height; row++)
		{
			System.arraycopy(pixels, (source.y + row) * bufferWidth + source.x, copyPixels, row * source.width, source.width);
		}

		final Rectangle target = geo.getTarget();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		graphics.drawImage(copy, target.x, target.y, target.width, target.height, null);

		final Point cursor = mouseMapper.getMappedFrom();
		if (cursor != null && !client.isMenuOpen())
		{
			drawTooltipsAt(graphics, cursor);
		}
		return null;
	}

	/**
	 * Draws the tooltips RuneLite has collected this frame, the way RuneLite does, but at
	 * the real cursor, then clears them so they are not drawn a second time.
	 */
	private void drawTooltipsAt(Graphics2D graphics, Point cursor)
	{
		final List<Tooltip> tooltips = tooltipManager.getTooltips();
		if (tooltips.isEmpty())
		{
			return;
		}

		try
		{
			graphics.setFont(runeLiteConfig.tooltipFont().getFont());

			final int x = Math.min(client.getCanvasWidth() - tooltipWidth, cursor.x);
			final int y = runeLiteConfig.tooltipPosition() == TooltipPositionType.ABOVE_CURSOR
				? Math.max(0, cursor.y - tooltipHeight)
				: Math.min(client.getCanvasHeight() - tooltipHeight, cursor.y + TOOLTIP_UNDER_OFFSET);

			int width = 0;
			int height = 0;
			for (Tooltip tooltip : tooltips)
			{
				final LayoutableRenderableEntity entity;
				if (tooltip.getComponent() != null)
				{
					entity = tooltip.getComponent();
					if (entity instanceof PanelComponent)
					{
						((PanelComponent) entity).setBackgroundColor(runeLiteConfig.overlayBackgroundColor());
					}
				}
				else
				{
					final TooltipComponent component = new TooltipComponent();
					component.setModIcons(client.getModIcons());
					component.setText(tooltip.getText());
					component.setBackgroundColor(runeLiteConfig.overlayBackgroundColor());
					entity = component;
				}

				entity.setPreferredLocation(new Point(x, y + height));
				final Dimension size = entity.render(graphics);
				height += size.height + TOOLTIP_PADDING;
				width = Math.max(width, size.width);
			}

			tooltipWidth = width;
			tooltipHeight = height;
		}
		finally
		{
			tooltipManager.clear();
		}
	}
}

package com.compassonly;

import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

/**
 * A copy of one right-click menu option, kept after the game has moved on, so the same
 * option can be put back into a later menu and still do the same thing.
 */
final class SavedMenuEntry
{
	private final String option;
	private final String target;
	private final MenuAction type;
	private final int identifier;
	private final int param0;
	private final int param1;
	private final int itemId;
	private final int worldViewId;
	private final boolean deprioritized;
	private final boolean forceLeftClick;

	private SavedMenuEntry(MenuEntry entry)
	{
		option = entry.getOption();
		target = entry.getTarget();
		type = entry.getType();
		identifier = entry.getIdentifier();
		param0 = entry.getParam0();
		param1 = entry.getParam1();
		itemId = entry.getItemId();
		worldViewId = entry.getWorldViewId();
		deprioritized = entry.isDeprioritized();
		forceLeftClick = entry.isForceLeftClick();
	}

	static SavedMenuEntry[] copyOf(MenuEntry[] entries)
	{
		final SavedMenuEntry[] saved = new SavedMenuEntry[entries.length];
		for (int i = 0; i < entries.length; i++)
		{
			saved[i] = new SavedMenuEntry(entries[i]);
		}
		return saved;
	}

	/**
	 * Replaces everything in the menu with the saved options, in the same order.
	 */
	static void restoreInto(Menu menu, SavedMenuEntry[] saved)
	{
		menu.setMenuEntries(new MenuEntry[0]);
		for (SavedMenuEntry entry : saved)
		{
			menu.createMenuEntry(-1)
				.setOption(entry.option)
				.setTarget(entry.target)
				.setType(entry.type)
				.setIdentifier(entry.identifier)
				.setParam0(entry.param0)
				.setParam1(entry.param1)
				.setItemId(entry.itemId)
				.setWorldViewId(entry.worldViewId)
				.setDeprioritized(entry.deprioritized)
				.setForceLeftClick(entry.forceLeftClick);
		}
	}
}

